package org.localpilot.android;
import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.widget.*;
public class MainActivity extends Activity {
 public static final String PREF="pilot";
 private TextView status;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(24,24,24,24);ScrollView scroll=new ScrollView(this);scroll.addView(box);setContentView(scroll);
  TextView title=new TextView(this);title.setText("LocalPilot Android"+(getPackageName().endsWith(".dev")?" Dev":"")+" · 0.3.3\nАвтополе и установленные игры");title.setTextSize(24);box.addView(title);
  TextView help=new TextView(this);help.setText("1. Включите службу LocalPilot в специальных возможностях.\n2. Откройте игру. В панели нажмите «Привязать».\n3. Введите X/Y в процентах и отправьте один жест.\n\nStop отменяет будущие действия; начатый жест до 120 мс может завершиться. Авто2048: открыть 2048, привязать окно, выделить квадрат поля, нажать Авто2048 и сверить матрицу. Только стандартная палитра, до 20 ходов. Нейросеть и RL ещё не подключены.\n\nСлужба видит элементы интерфейса активного окна. По вашей кнопке Авто2048 получает снимки экрана, читает выделенное поле в оперативной памяти. Кадры не сохраняются и не передаются. Разрешение можно отозвать в настройках Android.");box.addView(help);
  button(box,"Открыть специальные возможности",()->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));
  TextView panelHelp=new TextView(this);panelHelp.setText("«Свернуть» оставляет STOP и продолжает текущий режим. «STOP и скрыть» прекращает работу и отзывает ввод. При ошибке чтения панель покажет READ и причину; в экспорте задержек доступны attempts/errors/last_error.");box.addView(panelHelp);
  button(box,"Показать панель",()->{if(PilotService.instance!=null)PilotService.instance.showPanel();else toast("Сначала включите службу");});
  button(box,"Выбрать установленную игру",()->startActivity(new Intent(this,GamePickerActivity.class)));
  TextView autoHelp=new TextView(this);autoHelp.setText("«Автополе» само привязывает открытое окно и ищет поле: точная разметка встроенных игр или стандартная палитра 2048. Панель передвигается с найденного поля. Перед ходами сверьте клетки и подтвердите ввод. Другие игры можно выбрать и управлять касаниями вручную; автоматические профили Doodle Jump и раннеров пока не готовы.");box.addView(autoHelp);
  button(box,"Открыть 2048",()->startActivity(new Intent(this,Game2048Activity.class)));
  button(box,"Крестики-нолики",()->startActivity(new Intent(this,MiniGamesActivity.class).putExtra("kind",0)));
  button(box,"Погаси свет",()->startActivity(new Intent(this,MiniGamesActivity.class).putExtra("kind",1)));
  button(box,"Открыть тестовую игру",()->startActivity(new Intent(this,DemoActivity.class)));
  button(box,"Включить сбор примеров",()->{if(PilotService.instance==null){toast("Сначала включите службу");return;}new AlertDialog.Builder(this).setTitle("Сохранять игровые примеры?").setMessage("В памяти приложения останутся только распознанные поля до/после и проверенное действие, без снимков. До 256 примеров / 256 КиБ. Это не обучение. Сбор включается до перезапуска службы или выключения. При ошибке записи управление остановится.").setPositiveButton("Включить",(d,w)->{if(PilotService.instance!=null)PilotService.instance.enableExamples();else toast("Служба отключена");}).setNegativeButton("Отмена",null).show();});
  button(box,"Выключить сбор примеров",()->{if(PilotService.instance!=null)PilotService.instance.disableExamples();});
  button(box,"Экспорт примеров",()->{if(PilotService.instance==null){toast("Сначала включите службу");return;}try{PilotService.instance.exportExamples();startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("text/plain").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"localpilot-experience-v1.log"),11);}catch(java.io.IOException e){toast("Хранилище недоступно; исходник сохранён");}});
  button(box,"Восстановить в пустое хранилище",()->{if(PilotService.instance==null){toast("Сначала включите службу");return;}PilotService.instance.disableExamples();new AlertDialog.Builder(this).setTitle("Восстановление примеров").setMessage("Файл будет проверен полностью. Восстановление разрешено только в пустое исправное хранилище. Имеющиеся примеры не заменяются. Импорт не включает обучение или управление.").setPositiveButton("Выбрать файл",(d,w)->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("text/*").addCategory(Intent.CATEGORY_OPENABLE),12)).setNegativeButton("Отмена",null).show();});
  button(box,"Экспорт задержек",()->{if(PilotService.instance==null){toast("Сначала включите службу");return;}PilotService.instance.exportMetrics();startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("text/plain").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"localpilot-latency.txt"),10);});
  button(box,"Экспорт журнала",()->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("text/plain").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"localpilot-audit.log"),9));
  button(box,"STOP и убрать панель",()->{if(PilotService.instance!=null)PilotService.instance.hidePanel();});
  status=new TextView(this);box.addView(status);
 }
 @Override public void onResume(){super.onResume();if(status!=null)status.setText(PilotService.instance==null?"Служба не подключена":"Служба подключена; после запуска всегда требуется новая привязка");}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if((request!=9&&request!=10&&request!=11&&request!=12)||result!=RESULT_OK||data==null)return;try{if(request==11||request==12){if(PilotService.instance==null){toast("Сначала включите службу");return;}if(request==11){byte[] samples=PilotService.instance.exportExamples();try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new java.io.IOException();out.write(samples);}toast("Примеры экспортированы, ввод остановлен");}else{try(java.io.InputStream in=getContentResolver().openInputStream(data.getData())){if(in==null)throw new java.io.IOException();int count=PilotService.instance.restoreExamples(ExperienceStore.bounded(in));toast("Восстановлено примеров: "+count+". Сбор и ввод выключены");}}return;}if(request==10){if(PilotService.instance==null){toast("Служба отключена: замеры RAM недоступны");return;}byte[] metrics=PilotService.instance.exportMetrics().getBytes(java.nio.charset.StandardCharsets.UTF_8);try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new java.io.IOException("Нет файла");out.write(metrics);}toast("Замеры экспортированы, ввод остановлен");return;}byte[] bytes=PilotService.instance!=null?PilotService.instance.exportAudit():new SafeJournal(new java.io.File(getFilesDir(),"audit-v1.log")).snapshot();try(java.io.OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new java.io.IOException("Нет файла");out.write(bytes);}toast("Экспортирован журнал метаданных без снимков");}catch(java.io.IOException e){toast("Операция не выполнена; существующие данные сохранены");}}
 private void button(LinearLayout b,String t,Runnable r){Button x=new Button(this);x.setText(t);x.setOnClickListener(v->r.run());b.addView(x);}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
